// Des: Read-only lists (notifications, requests, inbox) and Messenger / buyer replies
// Flo: open the page (halt checks apply) > read item text with a small script > print numbered lines; replies: unread threads > template or AI draft > send through the DM job (new people need approval)
// I/O: what name or Args (caller) > printed lines, count; replies are sent only in --live
// ===================================================================
const std = @import("std"); const task = @import("ru-task-runn.zig"); const dmsg = @import("ru-dmsg-main.zig"); const post = @import("ru-post-main.zig");
const CF = .{ .arts = "Array.from(document.querySelectorAll('[role=article],[role=listitem],[role=row]')).map(function(e){return e.innerText.split('\\n')[0].trim()})", .thrs = "Array.from(document.querySelectorAll('a[href*=\"/messages/t/\"]')).map(function(a){return (a.getAttribute('aria-label')||a.innerText).trim()})", .unrd = "Array.from(document.querySelectorAll('a[href*=\"/messages/t/\"]')).filter(function(a){return /unread|chưa đọc/i.test((a.getAttribute('aria-label')||'')+' '+a.innerText)}).map(function(a){return a.getAttribute('href')})", .tpre = "/messages/t/", .aipr = "Write one short, friendly reply (max 25 words, same language) to a Facebook message that says: " };
pub const Kind = enum { noti, requests, birthdays, inbox, market_inbox, msgr_requests };
pub fn kindOf(name: []const u8) ?Kind { if (std.mem.eql(u8, name, "noti")) return .noti; if (std.mem.eql(u8, name, "requests")) return .requests; if (std.mem.eql(u8, name, "birthdays")) return .birthdays; if (std.mem.eql(u8, name, "inbox")) return .inbox; if (std.mem.eql(u8, name, "market-inbox")) return .market_inbox; if (std.mem.eql(u8, name, "msgr-requests")) return .msgr_requests; return null; }
pub fn readRun(ctx: *task.Ctx, name: []const u8) !u32 { const kin = kindOf(name) orelse return error.NoJob; const path = switch (kin) { .noti => ctx.conf.path_noti_comm, .requests => ctx.conf.path_frie_requ, .birthdays => ctx.conf.path_birt_main, .inbox => ctx.conf.path_msgr_main, .market_inbox => ctx.conf.path_mark_inbx, .msgr_requests => ctx.conf.path_msgr_requ }; try task.visit(ctx, path); const expr = switch (kin) { .inbox, .market_inbox => CF.thrs, else => CF.arts }; const items = try task.jsList(ctx, expr); for (items, 0..) |txt, idx| task.say(ctx, "{d}. {s}", .{ idx + 1, post.cutUtf8(txt, 80) }); if (items.len == 0) task.say(ctx, "nothing found", .{}); return @intCast(items.len); }
pub fn threadId(href: []const u8) ?[]const u8 { const at = std.mem.find(u8, href, CF.tpre) orelse return null; const rest = href[at + CF.tpre.len ..]; var end: usize = 0; while (end < rest.len and rest[end] != '/' and rest[end] != '?') end += 1; if (end == 0) return null; return rest[0..end]; }
pub fn pickFrom(ctx: *task.Ctx, list: []const []const u8, seed: []const u8) ![]const u8 { if (ctx.conf.smar_mode_enab) { if (ctx.draft) |drf| { const prm = try std.fmt.allocPrint(ctx.aren, "{s}{s}", .{ CF.aipr, seed }); if (drf(ctx, prm)) |txt| { const trm = std.mem.trim(u8, txt, " \r\n\""); if (trm.len > 0 and trm.len < 600) return trm; } else |_| {} } } if (list.len == 0) return "Thank you!"; return list[std.hash.Wyhash.hash(0, seed) % list.len]; }
pub fn msgrReply(ctx: *task.Ctx, args: task.Args, market: bool) !u32 { try task.visit(ctx, if (market) ctx.conf.path_mark_inbx else ctx.conf.path_msgr_main); const hrefs = try task.jsList(ctx, CF.unrd); var did: u32 = 0; for (hrefs) |href| { if (did >= args.maxn) break; const who = threadId(href) orelse continue; const rep = try pickFrom(ctx, if (market) ctx.conf.inqu_temp_list else ctx.conf.repl_temp_list, href); const out = dmsg.dmRun(ctx, .{ .to = who, .text = rep }) catch |err| { if (err == error.NeedApprove or err == error.Dupe or err == error.NoElement or err == error.Drift) { task.say(ctx, "skipped thread {s} ({s})", .{ who, @errorName(err) }); continue; } return err; }; if (out != .dupe) did += 1; } return did; }
